public class InnerBrandBrandColorPaletteFactory(Action<Humidifier.QuickSight.BrandTypes.BrandColorPalette> factoryAction = null) : SubResourceFactory<Humidifier.QuickSight.BrandTypes.BrandColorPalette>
{

    internal InnerBrandPaletteFactory SecondaryFactory { get; set; }

    internal InnerBrandPaletteFactory WarningFactory { get; set; }

    internal InnerBrandPaletteFactory AccentFactory { get; set; }

    internal InnerBrandPaletteFactory PrimaryFactory { get; set; }

    internal InnerBrandPaletteFactory DangerFactory { get; set; }

    internal InnerBrandPaletteFactory MeasureFactory { get; set; }

    internal InnerBrandPaletteFactory DimensionFactory { get; set; }

    internal InnerBrandPaletteFactory InfoFactory { get; set; }

    internal InnerBrandPaletteFactory SuccessFactory { get; set; }

    protected override Humidifier.QuickSight.BrandTypes.BrandColorPalette Create()
    {
        var brandColorPaletteResult = CreateBrandColorPalette();
        factoryAction?.Invoke(brandColorPaletteResult);

        return brandColorPaletteResult;
    }

    private Humidifier.QuickSight.BrandTypes.BrandColorPalette CreateBrandColorPalette()
    {
        var brandColorPaletteResult = new Humidifier.QuickSight.BrandTypes.BrandColorPalette();

        return brandColorPaletteResult;
    }
    public override void CreateChildren(Humidifier.QuickSight.BrandTypes.BrandColorPalette result)
    {
        base.CreateChildren(result);

        result.Secondary ??= SecondaryFactory?.Build();
        result.Warning ??= WarningFactory?.Build();
        result.Accent ??= AccentFactory?.Build();
        result.Primary ??= PrimaryFactory?.Build();
        result.Danger ??= DangerFactory?.Build();
        result.Measure ??= MeasureFactory?.Build();
        result.Dimension ??= DimensionFactory?.Build();
        result.Info ??= InfoFactory?.Build();
        result.Success ??= SuccessFactory?.Build();
    }

} // End Of Class

